"""Kmart multi-DC delivery routing — seed program for AlphaEvolve.

A routing plan is a list of truck routes. Each route starts and ends at one
distribution centre (DC) and visits a sequence of stores whose total demand
must not exceed the truck capacity. Every store must be visited exactly once
across the whole plan.

Cost of a plan = sum over routes of (route distance km * cost_per_km
                                     + fixed_cost_per_route).

Only build_routes() between the EVOLVE-BLOCK markers may be changed. It must
return a list of dicts: [{"dc": <dc_id>, "stores": [<store_id>, ...]}, ...].
"""
import math


def dist(a, b):
    return math.hypot(a["x"] - b["x"], a["y"] - b["y"])


# EVOLVE-BLOCK-START
def build_routes(dcs, stores, capacity):
    # Map for quick store lookup
    store_map = {s["id"]: s for s in stores}
    dc_map = {d["id"]: d for d in dcs}

    # Helper to calculate route distance for a sequence of store IDs and a DC ID
    def route_dist(dc_id, store_ids):
        if not store_ids:
            return 0.0
        dc_node = dc_map[dc_id]
        d = dist(dc_node, store_map[store_ids[0]])
        for i in range(len(store_ids) - 1):
            d += dist(store_map[store_ids[i]], store_map[store_ids[i+1]])
        d += dist(store_map[store_ids[-1]], dc_node)
        return d

    # 2-Opt local search to optimize store sequence within a single route
    def optimize_sequence(dc_id, store_ids):
        if len(store_ids) <= 2:
            return store_ids
        best_seq = list(store_ids)
        best_d = route_dist(dc_id, best_seq)
        improved = True
        while improved:
            improved = False
            for i in range(len(best_seq) - 1):
                for j in range(i + 1, len(best_seq)):
                    # Try reversing the segment from i to j
                    new_seq = best_seq[:i] + best_seq[i:j+1][::-1] + best_seq[j+1:]
                    new_d = route_dist(dc_id, new_seq)
                    if new_d < best_d - 1e-5:
                        best_seq = new_seq
                        best_d = new_d
                        improved = True
                        break
                if improved:
                    break
        return best_seq

    # Initialize routes list: each route is {"dc": dc_id, "stores": [store_ids], "load": total_load}
    routes = []
    unassigned = list(stores)
    # Sort unassigned stores by demand descending to handle high-demand items first (bin-packing heuristic)
    unassigned.sort(key=lambda s: s["demand"], reverse=True)

    for store in unassigned:
        best_insertion = None  # (route_index, insert_position, cost_increase)
        second_best_increase = float('inf')
        best_increase = float('inf')

        # 1. Evaluate inserting into existing routes
        for r_idx, r in enumerate(routes):
            if r["load"] + store["demand"] <= capacity:
                # Find best insertion position in this route
                for pos in range(len(r["stores"]) + 1):
                    temp_stores = r["stores"][:pos] + [store["id"]] + r["stores"][pos:]
                    old_d = route_dist(r["dc"], r["stores"])
                    new_d = route_dist(r["dc"], temp_stores)
                    cost_inc = (new_d - old_d) * 2.5
                    if cost_inc < best_increase:
                        second_best_increase = best_increase
                        best_increase = cost_inc
                        best_insertion = (r_idx, pos, cost_inc)
                    elif cost_inc < second_best_increase:
                        second_best_increase = cost_inc

        # 2. Evaluate opening a new route for this store at any DC
        for dc in dcs:
            # Cost of opening a new route
            new_route_cost = 300.0 + (route_dist(dc["id"], [store["id"]]) * 2.5)
            if new_route_cost < best_increase:
                second_best_increase = best_increase
                best_increase = new_route_cost
                best_insertion = ("NEW", dc["id"], new_route_cost)
            elif new_route_cost < second_best_increase:
                second_best_increase = new_route_cost

        # Regret-based decision: Insert store into its best option
        if best_insertion[0] == "NEW":
            dc_id = best_insertion[1]
            routes.append({
                "dc": dc_id,
                "stores": [store["id"]],
                "load": store["demand"]
            })
        else:
            r_idx, pos, _ = best_insertion
            routes[r_idx]["stores"].insert(pos, store["id"])
            routes[r_idx]["load"] += store["demand"]

    # Post-processing: Optimize each route's sequence and assign to its optimal DC
    final_routes = []
    for r in routes:
        if not r["stores"]:
            continue
        # Find the absolute best DC for this completed route's sequence
        best_dc = r["dc"]
        best_cost = float('inf')
        best_seq = r["stores"]
        for dc in dcs:
            seq_opt = optimize_sequence(dc["id"], r["stores"])
            c = route_dist(dc["id"], seq_opt) * 2.5 + 300.0
            if c < best_cost:
                best_cost = c
                best_dc = dc["id"]
                best_seq = seq_opt

        final_routes.append({
            "dc": best_dc,
            "stores": best_seq
        })

    return final_routes
# EVOLVE-BLOCK-END


def solve(instance):
    return build_routes(instance["dcs"], instance["stores"],
                        instance["truck_capacity"])

"""Kmart multi-DC delivery routing — seed program for AlphaEvolve.

A routing plan is a list of truck routes. Each route starts and ends at one
distribution centre (DC) and visits a sequence of stores whose total demand
must not exceed the truck capacity. Every store must be visited exactly once
across the whole plan.

Cost of a plan = sum over routes of (route distance km * cost_per_km
                                     + fixed_cost_per_route).

Only build_routes() between the EVOLVE-BLOCK markers may be changed. It must
return a list of dicts: [{"dc": <dc_id>, "stores": [<store_id>, ...]}, ...].
"""
import math


def dist(a, b):
    return math.hypot(a["x"] - b["x"], a["y"] - b["y"])


# EVOLVE-BLOCK-START
def build_routes(dcs, stores, capacity):
    # Map for quick lookup
    store_map = {s["id"]: s for s in stores}
    dc_map = {d["id"]: d for d in dcs}

    # Precompute distances to optimize execution speed
    dist_memo = {}
    def get_dist(id1, id2):
        key = (id1, id2) if id1 < id2 else (id2, id1)
        if key not in dist_memo:
            loc1 = store_map[id1] if id1 in store_map else dc_map[id1]
            loc2 = store_map[id2] if id2 in store_map else dc_map[id2]
            dist_memo[key] = dist(loc1, loc2)
        return dist_memo[key]

    def route_cost_val(dc_id, store_ids):
        if not store_ids:
            return 0.0
        d_cost = get_dist(dc_id, store_ids[0])
        for i in range(len(store_ids) - 1):
            d_cost += get_dist(store_ids[i], store_ids[i+1])
        d_cost += get_dist(store_ids[-1], dc_id)
        return d_cost * 2.5 + 300.0

    def optimize_route_2opt(dc_id, store_ids):
        if len(store_ids) < 3:
            return store_ids, route_cost_val(dc_id, store_ids)

        best_stores = list(store_ids)
        best_cost = route_cost_val(dc_id, best_stores)
        improved = True
        while improved:
            improved = False
            for i in range(len(best_stores) - 1):
                for j in range(i + 1, len(best_stores)):
                    new_stores = best_stores[:i] + best_stores[i:j+1][::-1] + best_stores[j+1:]
                    new_cost = route_cost_val(dc_id, new_stores)
                    if new_cost < best_cost - 1e-5:
                        best_stores = new_stores
                        best_cost = new_cost
                        improved = True
                        break
                if improved:
                    break
        return best_stores, best_cost

    # Run Clarke-Wright and routing independently for each DC,
    # then resolve the global allocation.
    best_overall_routes = []
    best_overall_cost = float('inf')

    # Multi-depot assignment strategies:
    # 1. Assignment to absolute nearest DC.
    # 2. Assignment based on DC-savings/affinity.
    # We can evaluate both and pick the best initial routes.
    strategies = ["nearest", "balanced_affinity"]

    for strategy in strategies:
        # Determine initial DC assignment
        dc_assignments = {d["id"]: [] for d in dcs}
        if strategy == "nearest":
            for s in stores:
                best_dc = min(dcs, key=lambda d: dist(s, d))
                dc_assignments[best_dc["id"]].append(s["id"])
        else:
            for s in stores:
                # Rank DCs based on proximity and assign with secondary bias
                sorted_dcs = sorted(dcs, key=lambda d: dist(s, d))
                dc_assignments[sorted_dcs[0]["id"]].append(s["id"])

        current_all_routes = []
        for dc_id, assigned_stores in dc_assignments.items():
            if not assigned_stores:
                continue

            # Start each assigned store as its own route
            dc_routes = []
            for s_id in assigned_stores:
                dc_routes.append({
                    "dc": dc_id,
                    "stores": [s_id],
                    "load": store_map[s_id]["demand"]
                })

            # Clarke-Wright Merging for this DC
            improved_merge = True
            while improved_merge:
                improved_merge = False
                best_saving = 0
                best_merge = None

                n_r = len(dc_routes)
                for i in range(n_r):
                    for j in range(i + 1, n_r):
                        r1, r2 = dc_routes[i], dc_routes[j]
                        if r1["load"] + r2["load"] > capacity:
                            continue

                        c1 = route_cost_val(dc_id, r1["stores"]) + route_cost_val(dc_id, r2["stores"])
                        options = [
                            r1["stores"] + r2["stores"],
                            r1["stores"] + r2["stores"][::-1],
                            r1["stores"][::-1] + r2["stores"],
                            r1["stores"][::-1] + r2["stores"][::-1]
                        ]
                        for opt in options:
                            c2 = route_cost_val(dc_id, opt)
                            saving = c1 - c2
                            if saving > best_saving:
                                best_saving = saving
                                best_merge = (i, j, opt)

                if best_merge is not None:
                    i, j, merged_stores = best_merge
                    dc_routes[i]["stores"] = merged_stores
                    dc_routes[i]["load"] += dc_routes[j]["load"]
                    dc_routes.pop(j)
                    improved_merge = True

            current_all_routes.extend(dc_routes)

        # Apply 2-opt to all routes in this strategy's set
        for r in current_all_routes:
            r["stores"], _ = optimize_route_2opt(r["dc"], r["stores"])

        # Inter-route improvement phase: relocations and swaps
        improved_inter = True
        while improved_inter:
            improved_inter = False
            # Try shifting a single store from one route to another (either same DC or different DC)
            for i in range(len(current_all_routes)):
                for j in range(len(current_all_routes)):
                    if i == j:
                        continue
                    r_src, r_dest = current_all_routes[i], current_all_routes[j]

                    for store_idx, s_id in enumerate(r_src["stores"]):
                        demand = store_map[s_id]["demand"]
                        if r_dest["load"] + demand <= capacity:
                            # Evaluate cost change if we move s_id from r_src to r_dest
                            old_src_cost = route_cost_val(r_src["dc"], r_src["stores"])
                            old_dest_cost = route_cost_val(r_dest["dc"], r_dest["stores"])

                            new_src_stores = r_src["stores"][:store_idx] + r_src["stores"][store_idx+1:]
                            # Test inserting into all positions of r_dest
                            best_insert_cost = float('inf')
                            best_insert_stores = []
                            for ins_idx in range(len(r_dest["stores"]) + 1):
                                temp_dest = r_dest["stores"][:ins_idx] + [s_id] + r_dest["stores"][ins_idx:]
                                temp_cost = route_cost_val(r_dest["dc"], temp_dest)
                                if temp_cost < best_insert_cost:
                                    best_insert_cost = temp_cost
                                    best_insert_stores = temp_dest

                            new_src_cost = route_cost_val(r_src["dc"], new_src_stores)

                            saving = (old_src_cost + old_dest_cost) - (new_src_cost + best_insert_cost)
                            if saving > 1e-5:
                                r_src["stores"] = new_src_stores
                                r_src["load"] -= demand
                                r_dest["stores"] = best_insert_stores
                                r_dest["load"] += demand
                                improved_inter = True
                                break
                    if improved_inter:
                        break
                if improved_inter:
                    break

            # Remove empty routes
            current_all_routes = [r for r in current_all_routes if r["stores"]]

        # Final evaluation of the strategy
        total_cost = sum(route_cost_val(r["dc"], r["stores"]) for r in current_all_routes)
        if total_cost < best_overall_cost:
            best_overall_cost = total_cost
            best_overall_routes = current_all_routes

    # Clean up empty routes & 2-opt optimize the best chosen solution
    final_routes = []
    for r in best_overall_routes:
        if r["stores"]:
            opt_stores, _ = optimize_route_2opt(r["dc"], r["stores"])
            final_routes.append({
                "dc": r["dc"],
                "stores": opt_stores
            })

    return final_routes
# EVOLVE-BLOCK-END


def solve(instance):
    return build_routes(instance["dcs"], instance["stores"],
                        instance["truck_capacity"])

"""Kmart multi-DC delivery routing — seed program for AlphaEvolve.

A routing plan is a list of truck routes. Each route starts and ends at one
distribution centre (DC) and visits a sequence of stores whose total demand
must not exceed the truck capacity. Every store must be visited exactly once
across the whole plan.

Cost of a plan = sum over routes of (route distance km * cost_per_km
                                     + fixed_cost_per_route).

Only build_routes() between the EVOLVE-BLOCK markers may be changed. It must
return a list of dicts: [{"dc": <dc_id>, "stores": [<store_id>, ...]}, ...].
"""
import math


def dist(a, b):
    return math.hypot(a["x"] - b["x"], a["y"] - b["y"])


# EVOLVE-BLOCK-START
def build_routes(dcs, stores, capacity):
    # Map store/DC ids to their dictionaries for quick lookup
    store_map = {s["id"]: s for s in stores}
    dc_map = {d["id"]: d for d in dcs}

    def get_route_distance(dc_id, store_ids):
        if not store_ids:
            return 0.0
        dc = dc_map[dc_id]
        total_dist = dist(dc, store_map[store_ids[0]])
        for i in range(len(store_ids) - 1):
            total_dist += dist(store_map[store_ids[i]], store_map[store_ids[i+1]])
        total_dist += dist(store_map[store_ids[-1]], dc)
        return total_dist

    def route_cost(dc_id, store_ids):
        if not store_ids:
            return 0.0
        return get_route_distance(dc_id, store_ids) * 2.5 + 300.0

    def optimize_2opt(dc_id, store_ids):
        """Standard 2-opt route refinement to minimize distance."""
        best_ids = list(store_ids)
        best_dist = get_route_distance(dc_id, best_ids)
        improved = True
        while improved:
            improved = False
            for i in range(len(best_ids) - 1):
                for j in range(i + 1, len(best_ids)):
                    new_ids = best_ids[:i] + list(reversed(best_ids[i:j+1])) + best_ids[j+1:]
                    new_dist = get_route_distance(dc_id, new_ids)
                    if new_dist < best_dist - 1e-6:
                        best_ids = new_ids
                        best_dist = new_dist
                        improved = True
                        break
                if improved:
                    break
        return best_ids

    # 1. Clarke-Wright Savings initialization per DC
    # Start by assigning each store to its nearest DC
    dc_assignments = {dc["id"]: [] for dc in dcs}
    for s in stores:
        best_dc = min(dcs, key=lambda d: dist(s, d))
        dc_assignments[best_dc["id"]].append(s["id"])

    routes = []
    for dc_id, assigned_stores in dc_assignments.items():
        if not assigned_stores:
            continue
        dc = dc_map[dc_id]
        # Initial routes: each store has its own route
        sub_routes = [[sid] for sid in assigned_stores]

        # Calculate savings
        savings = []
        for i in range(len(assigned_stores)):
            for j in range(i + 1, len(assigned_stores)):
                s1 = store_map[assigned_stores[i]]
                s2 = store_map[assigned_stores[j]]
                saving = dist(dc, s1) + dist(dc, s2) - dist(s1, s2)
                savings.append((saving, s1["id"], s2["id"]))

        # Sort savings in descending order
        savings.sort(key=lambda x: x[0], reverse=True)

        for saving, s1_id, s2_id in savings:
            # Find routes containing s1 and s2
            r1_idx, r2_idx = -1, -1
            for idx, r in enumerate(sub_routes):
                if s1_id in r:
                    r1_idx = idx
                if s2_id in r:
                    r2_idx = idx

            if r1_idx != -1 and r2_idx != -1 and r1_idx != r2_idx:
                r1 = sub_routes[r1_idx]
                r2 = sub_routes[r2_idx]

                # Check demand capacity
                total_demand = sum(store_map[sid]["demand"] for sid in r1 + r2)
                if total_demand <= capacity:
                    # Check if s1 and s2 are at the boundaries of their respective routes
                    if (r1[-1] == s1_id and r2[0] == s2_id):
                        new_route = r1 + r2
                    elif (r1[0] == s1_id and r2[-1] == s2_id):
                        new_route = r2 + r1
                    elif (r1[-1] == s1_id and r2[-1] == s2_id):
                        new_route = r1 + list(reversed(r2))
                    elif (r1[0] == s1_id and r2[0] == s2_id):
                        new_route = list(reversed(r1)) + r2
                    else:
                        continue

                    # Merge routes
                    sub_routes.pop(max(r1_idx, r2_idx))
                    sub_routes.pop(min(r1_idx, r2_idx))
                    sub_routes.append(new_route)

        for sr in sub_routes:
            opt_sr = optimize_2opt(dc_id, sr)
            routes.append({"dc": dc_id, "stores": opt_sr})

    # 2. Inter-route Optimization & Local Search
    # Attempt to move single stores to other routes (including other DCs) if it reduces global cost
    improved = True
    while improved:
        improved = False
        for r_idx, route in enumerate(routes):
            if len(route["stores"]) <= 1:
                # We can try to completely empty this route if we move its single store
                pass
            for s_idx, store_id in enumerate(route["stores"]):
                store_demand = store_map[store_id]["demand"]
                # Try to insert store_id into any other route
                for target_idx, target_route in enumerate(routes):
                    if r_idx == target_idx:
                        continue
                    # Check capacity
                    target_demand = sum(store_map[sid]["demand"] for sid in target_route["stores"])
                    if target_demand + store_demand <= capacity:
                        # Try all insertion positions
                        best_insert_pos = -1
                        best_cost_diff = 0.0 # seeking negative cost difference

                        current_route_stores = [sid for sid in route["stores"] if sid != store_id]
                        old_routes_cost = route_cost(route["dc"], route["stores"]) + route_cost(target_route["dc"], target_route["stores"])

                        for p in range(len(target_route["stores"]) + 1):
                            candidate_target = target_route["stores"][:p] + [store_id] + target_route["stores"][p:]
                            candidate_target_opt = optimize_2opt(target_route["dc"], candidate_target)

                            new_routes_cost = route_cost(route["dc"], current_route_stores) + route_cost(target_route["dc"], candidate_target_opt)
                            cost_diff = new_routes_cost - old_routes_cost
                            if cost_diff < best_cost_diff - 1e-4:
                                best_cost_diff = cost_diff
                                best_insert_pos = p
                                best_target_stores = candidate_target_opt

                        if best_insert_pos != -1:
                            route["stores"] = current_route_stores
                            target_route["stores"] = best_target_stores
                            improved = True
                            break
                if improved:
                    break
            if improved:
                break
        # Clean up empty routes
        routes = [r for r in routes if len(r["stores"]) > 0]

    # Final pass 2-opt to guarantee optimal ordering
    for r in routes:
        r["stores"] = optimize_2opt(r["dc"], r["stores"])

    return routes
# EVOLVE-BLOCK-END


def solve(instance):
    return build_routes(instance["dcs"], instance["stores"],
                        instance["truck_capacity"])

"""Kmart multi-DC delivery routing — seed program for AlphaEvolve.

A routing plan is a list of truck routes. Each route starts and ends at one
distribution centre (DC) and visits a sequence of stores whose total demand
must not exceed the truck capacity. Every store must be visited exactly once
across the whole plan.

Cost of a plan = sum over routes of (route distance km * cost_per_km
                                     + fixed_cost_per_route).

Only build_routes() between the EVOLVE-BLOCK markers may be changed. It must
return a list of dicts: [{"dc": <dc_id>, "stores": [<store_id>, ...]}, ...].
"""
import math


def dist(a, b):
    return math.hypot(a["x"] - b["x"], a["y"] - b["y"])


# EVOLVE-BLOCK-START
def build_routes(dcs, stores, capacity):
    # Map store and DC IDs to dicts for quick lookup
    store_map = {s["id"]: s for s in stores}
    dc_map = {d["id"]: d for d in dcs}

    # Step 1: Initialize each store in its own route
    routes = []
    for s in stores:
        routes.append({
            "stores": [s["id"]],
            "load": s["demand"]
        })

    # Step 2: Compute global savings between any two stores using their closest DCs
    savings = []
    for i in range(len(stores)):
        s1 = stores[i]
        d1 = min(dist(s1, dc) for dc in dcs)
        for j in range(i + 1, len(stores)):
            s2 = stores[j]
            d2 = min(dist(s2, dc) for dc in dcs)
            # Savings = cost of visiting separately vs merged
            s_val = d1 + d2 - dist(s1, s2)
            # Incorporate fixed cost saving of 300.0 (converted to distance equivalent: 300 / cost_per_km = 120)
            savings.append((s_val + 120.0, s1["id"], s2["id"]))

    # Sort savings in descending order
    savings.sort(key=lambda x: x[0], reverse=True)

    # Step 3: Merge routes globally based on savings
    for sav, id1, id2 in savings:
        r1_idx, r2_idx = None, None
        for idx, r in enumerate(routes):
            if r["stores"][0] == id1 or r["stores"][-1] == id1:
                r1_idx = idx
            if r["stores"][0] == id2 or r["stores"][-1] == id2:
                r2_idx = idx

        if r1_idx is not None and r2_idx is not None and r1_idx != r2_idx:
            r1 = routes[r1_idx]
            r2 = routes[r2_idx]
            if r1["load"] + r2["load"] <= capacity:
                # Merge the stores in correct orientation
                if r1["stores"][-1] == id1 and r2["stores"][0] == id2:
                    new_stores = r1["stores"] + r2["stores"]
                elif r1["stores"][-1] == id1 and r2["stores"][-1] == id2:
                    new_stores = r1["stores"] + list(reversed(r2["stores"]))
                elif r1["stores"][0] == id1 and r2["stores"][0] == id2:
                    new_stores = list(reversed(r1["stores"])) + r2["stores"]
                else:
                    new_stores = r2["stores"] + r1["stores"]

                r1["stores"] = new_stores
                r1["load"] += r2["load"]
                routes.pop(r2_idx)

    # Step 4: Refine each route with 2-opt and dynamically choose the optimal DC
    refined_routes = []
    for r in routes:
        route_stores = [store_map[sid] for sid in r["stores"]]

        # Determine the best DC for this completed route
        def route_cost(dc_node, r_nodes):
            return (dist(dc_node, r_nodes[0]) + 
                    sum(dist(r_nodes[k], r_nodes[k+1]) for k in range(len(r_nodes)-1)) + 
                    dist(r_nodes[-1], dc_node))

        best_dc = min(dcs, key=lambda d: route_cost(d, route_stores))

        # 2-opt local search optimization using the selected best DC
        improved = True
        while improved:
            improved = False
            best_dist = route_cost(best_dc, route_stores)

            for i in range(len(route_stores) - 1):
                for j in range(i + 1, len(route_stores)):
                    new_route = route_stores[:i] + list(reversed(route_stores[i:j+1])) + route_stores[j+1:]
                    new_dist = route_cost(best_dc, new_route)
                    if new_dist < best_dist - 1e-4:
                        route_stores = new_route
                        best_dist = new_dist
                        improved = True
                        break
                if improved:
                    break

        refined_routes.append({
            "dc": best_dc["id"],
            "stores": [s["id"] for s in route_stores]
        })

    return refined_routes
# EVOLVE-BLOCK-END


def solve(instance):
    return build_routes(instance["dcs"], instance["stores"],
                        instance["truck_capacity"])

"""Kmart multi-DC delivery routing — seed program for AlphaEvolve.

A routing plan is a list of truck routes. Each route starts and ends at one
distribution centre (DC) and visits a sequence of stores whose total demand
must not exceed the truck capacity. Every store must be visited exactly once
across the whole plan.

Cost of a plan = sum over routes of (route distance km * cost_per_km
                                     + fixed_cost_per_route).

Only build_routes() between the EVOLVE-BLOCK markers may be changed. It must
return a list of dicts: [{"dc": <dc_id>, "stores": [<store_id>, ...]}, ...].
"""
import math


def dist(a, b):
    return math.hypot(a["x"] - b["x"], a["y"] - b["y"])


# EVOLVE-BLOCK-START
def build_routes(dcs, stores, capacity):
    # Map store/DC ids to their dictionaries for quick lookup
    store_map = {s["id"]: s for s in stores}
    dc_map = {d["id"]: d for d in dcs}

    def get_route_distance(dc_id, store_ids):
        if not store_ids:
            return 0.0
        dc = dc_map[dc_id]
        total_dist = dist(dc, store_map[store_ids[0]])
        for i in range(len(store_ids) - 1):
            total_dist += dist(store_map[store_ids[i]], store_map[store_ids[i+1]])
        total_dist += dist(store_map[store_ids[-1]], dc)
        return total_dist

    def route_cost(dc_id, store_ids):
        if not store_ids:
            return 0.0
        return get_route_distance(dc_id, store_ids) * 2.5 + 300.0

    def optimize_2opt(dc_id, store_ids):
        """Standard 2-opt route refinement to minimize distance."""
        best_ids = list(store_ids)
        best_dist = get_route_distance(dc_id, best_ids)
        improved = True
        while improved:
            improved = False
            for i in range(len(best_ids) - 1):
                for j in range(i + 1, len(best_ids)):
                    new_ids = best_ids[:i] + list(reversed(best_ids[i:j+1])) + best_ids[j+1:]
                    new_dist = get_route_distance(dc_id, new_ids)
                    if new_dist < best_dist - 1e-6:
                        best_ids = new_ids
                        best_dist = new_dist
                        improved = True
                        break
                if improved:
                    break
        return best_ids

    # 1. Clarke-Wright Savings initialization per DC
    # Start by assigning each store to its nearest DC
    dc_assignments = {dc["id"]: [] for dc in dcs}
    for s in stores:
        best_dc = min(dcs, key=lambda d: dist(s, d))
        dc_assignments[best_dc["id"]].append(s["id"])

    routes = []
    for dc_id, assigned_stores in dc_assignments.items():
        if not assigned_stores:
            continue
        dc = dc_map[dc_id]
        # Initial routes: each store has its own route
        sub_routes = [[sid] for sid in assigned_stores]

        # Calculate savings
        savings = []
        for i in range(len(assigned_stores)):
            for j in range(i + 1, len(assigned_stores)):
                s1 = store_map[assigned_stores[i]]
                s2 = store_map[assigned_stores[j]]
                saving = dist(dc, s1) + dist(dc, s2) - dist(s1, s2)
                savings.append((saving, s1["id"], s2["id"]))

        # Sort savings in descending order
        savings.sort(key=lambda x: x[0], reverse=True)

        for saving, s1_id, s2_id in savings:
            # Find routes containing s1 and s2
            r1_idx, r2_idx = -1, -1
            for idx, r in enumerate(sub_routes):
                if s1_id in r:
                    r1_idx = idx
                if s2_id in r:
                    r2_idx = idx

            if r1_idx != -1 and r2_idx != -1 and r1_idx != r2_idx:
                r1 = sub_routes[r1_idx]
                r2 = sub_routes[r2_idx]

                # Check demand capacity
                total_demand = sum(store_map[sid]["demand"] for sid in r1 + r2)
                if total_demand <= capacity:
                    # Check if s1 and s2 are at the boundaries of their respective routes
                    if (r1[-1] == s1_id and r2[0] == s2_id):
                        new_route = r1 + r2
                    elif (r1[0] == s1_id and r2[-1] == s2_id):
                        new_route = r2 + r1
                    elif (r1[-1] == s1_id and r2[-1] == s2_id):
                        new_route = r1 + list(reversed(r2))
                    elif (r1[0] == s1_id and r2[0] == s2_id):
                        new_route = list(reversed(r1)) + r2
                    else:
                        continue

                    # Merge routes
                    sub_routes.pop(max(r1_idx, r2_idx))
                    sub_routes.pop(min(r1_idx, r2_idx))
                    sub_routes.append(new_route)

        for sr in sub_routes:
            opt_sr = optimize_2opt(dc_id, sr)
            routes.append({"dc": dc_id, "stores": opt_sr})

    # 2. Inter-route Optimization & Local Search
    # Attempt to relocate or swap stores between routes to reduce total cost
    improved = True
    while improved:
        improved = False

        # Check alternative DCs for all existing routes
        for r in routes:
            best_dc = r["dc"]
            best_c = route_cost(r["dc"], r["stores"])
            for dc in dcs:
                if dc["id"] != r["dc"]:
                    c = route_cost(dc["id"], r["stores"])
                    if c < best_c - 1e-4:
                        best_c = c
                        best_dc = dc["id"]
            if r["dc"] != best_dc:
                r["dc"] = best_dc
                improved = True

        for r_idx, route in enumerate(routes):
            for s_idx, store_id in enumerate(route["stores"]):
                store_demand = store_map[store_id]["demand"]

                # Try relocation (moving store_id to target_route)
                for target_idx, target_route in enumerate(routes):
                    if r_idx == target_idx:
                        continue
                    target_demand = sum(store_map[sid]["demand"] for sid in target_route["stores"])
                    if target_demand + store_demand <= capacity:
                        current_route_stores = [sid for sid in route["stores"] if sid != store_id]
                        old_routes_cost = route_cost(route["dc"], route["stores"]) + route_cost(target_route["dc"], target_route["stores"])

                        # Find best insertion index in target route
                        best_insert_pos = -1
                        best_cost_diff = 0.0
                        best_target_stores = []
                        for p in range(len(target_route["stores"]) + 1):
                            candidate_target = target_route["stores"][:p] + [store_id] + target_route["stores"][p:]
                            candidate_target_opt = optimize_2opt(target_route["dc"], candidate_target)
                            new_routes_cost = route_cost(route["dc"], current_route_stores) + route_cost(target_route["dc"], candidate_target_opt)
                            cost_diff = new_routes_cost - old_routes_cost
                            if cost_diff < best_cost_diff - 1e-4:
                                best_cost_diff = cost_diff
                                best_insert_pos = p
                                best_target_stores = candidate_target_opt

                        if best_insert_pos != -1:
                            route["stores"] = current_route_stores
                            target_route["stores"] = best_target_stores
                            improved = True
                            break

                if improved:
                    break

                # Try swap (exchanging store_id with target_store_id)
                for target_idx, target_route in enumerate(routes):
                    if r_idx == target_idx:
                        continue
                    r_demand_without = sum(store_map[sid]["demand"] for sid in route["stores"] if sid != store_id)
                    t_demand = sum(store_map[sid]["demand"] for sid in target_route["stores"])

                    for ts_idx, target_store_id in enumerate(target_route["stores"]):
                        target_store_demand = store_map[target_store_id]["demand"]
                        if r_demand_without + target_store_demand <= capacity and t_demand - target_store_demand + store_demand <= capacity:
                            old_routes_cost = route_cost(route["dc"], route["stores"]) + route_cost(target_route["dc"], target_route["stores"])

                            candidate_r = [sid for sid in route["stores"] if sid != store_id] + [target_store_id]
                            candidate_r_opt = optimize_2opt(route["dc"], candidate_r)

                            candidate_t = [sid for sid in target_route["stores"] if sid != target_store_id] + [store_id]
                            candidate_t_opt = optimize_2opt(target_route["dc"], candidate_t)

                            new_routes_cost = route_cost(route["dc"], candidate_r_opt) + route_cost(target_route["dc"], candidate_t_opt)
                            if new_routes_cost < old_routes_cost - 1e-4:
                                route["stores"] = candidate_r_opt
                                target_route["stores"] = candidate_t_opt
                                improved = True
                                break
                    if improved:
                        break
            if improved:
                break

        # Clean up empty routes
        routes = [r for r in routes if len(r["stores"]) > 0]

    # Final pass 2-opt to guarantee optimal ordering and DC choice
    for r in routes:
        best_dc = r["dc"]
        best_c = route_cost(r["dc"], r["stores"])
        for dc in dcs:
            c = route_cost(dc["id"], r["stores"])
            if c < best_c:
                best_c = c
                best_dc = dc["id"]
        r["dc"] = best_dc
        r["stores"] = optimize_2opt(r["dc"], r["stores"])

    return routes
# EVOLVE-BLOCK-END


def solve(instance):
    return build_routes(instance["dcs"], instance["stores"],
                        instance["truck_capacity"])

"""Kmart multi-DC delivery routing — seed program for AlphaEvolve.

A routing plan is a list of truck routes. Each route starts and ends at one
distribution centre (DC) and visits a sequence of stores whose total demand
must not exceed the truck capacity. Every store must be visited exactly once
across the whole plan.

Cost of a plan = sum over routes of (route distance km * cost_per_km
                                     + fixed_cost_per_route).

Only build_routes() between the EVOLVE-BLOCK markers may be changed. It must
return a list of dicts: [{"dc": <dc_id>, "stores": [<store_id>, ...]}, ...].
"""
import math


def dist(a, b):
    return math.hypot(a["x"] - b["x"], a["y"] - b["y"])


# EVOLVE-BLOCK-START
def build_routes(dcs, stores, capacity):
    # Map for quick store lookup by ID
    store_map = {s["id"]: s for s in stores}

    # Cache all pairwise distances up front
    dc_map = {d["id"]: d for d in dcs}
    memo_dist = {}

    def get_dist(id1, id2):
        key = (id1, id2) if id1 < id2 else (id2, id1)
        if key not in memo_dist:
            e1 = store_map[id1] if id1 in store_map else dc_map[id1]
            e2 = store_map[id2] if id2 in store_map else dc_map[id2]
            memo_dist[key] = dist(e1, e2)
        return memo_dist[key]

    def route_cost(dc_id, store_ids):
        if not store_ids:
            return 0.0
        d_cost = get_dist(dc_id, store_ids[0])
        for i in range(len(store_ids) - 1):
            d_cost += get_dist(store_ids[i], store_ids[i+1])
        d_cost += get_dist(store_ids[-1], dc_id)
        return d_cost * 2.5 + 300.0

    def optimize_route_2opt(dc_id, store_ids):
        best_stores = list(store_ids)
        best_c = route_cost(dc_id, best_stores)
        improved = True
        while improved:
            improved = False
            for i in range(len(best_stores) - 1):
                for j in range(i + 1, len(best_stores)):
                    new_stores = best_stores[:i] + best_stores[i:j+1][::-1] + best_stores[j+1:]
                    new_c = route_cost(dc_id, new_stores)
                    if new_c < best_c - 1e-5:
                        best_stores = new_stores
                        best_c = new_c
                        improved = True
                        break
                if improved:
                    break
        return best_stores, best_c

    # 1. Initialize: Assign each store to its nearest DC as a single-store route
    routes = []
    for s in stores:
        best_dc = min(dcs, key=lambda d: dist(s, d))
        routes.append({
            "dc": best_dc["id"],
            "stores": [s["id"]],
            "load": s["demand"]
        })

    # 2. Parallel Savings: Continually merge routes that yield the maximum saving across all DCs.
    # By optimizing the DC assignment during the merge, we bypass the need for an expensive swap search.
    improved = True
    while improved:
        improved = False
        best_saving = 0.0
        best_merge = None  # (idx_i, idx_j, merged_stores, best_dc_id)

        n = len(routes)
        for i in range(n):
            for j in range(i + 1, n):
                r1, r2 = routes[i], routes[j]
                if r1["load"] + r2["load"] > capacity:
                    continue

                c1 = route_cost(r1["dc"], r1["stores"]) + route_cost(r2["dc"], r2["stores"])

                # Check merge combinations across all DCs on the fly
                for dc_candidate in dcs:
                    dc_id = dc_candidate["id"]
                    for opt in [r1["stores"] + r2["stores"], r2["stores"] + r1["stores"]]:
                        opt_stores, c2 = optimize_route_2opt(dc_id, opt)
                        saving = c1 - c2
                        if saving > best_saving + 1e-5:
                            best_saving = saving
                            best_merge = (i, j, opt_stores, dc_id)

        if best_merge is not None:
            i, j, merged_stores, best_dc_id = best_merge
            routes[i]["stores"] = merged_stores
            routes[i]["load"] += routes[j]["load"]
            routes[i]["dc"] = best_dc_id
            routes.pop(j)
            improved = True

    # Final run of 2-opt over all resulting routes to ensure absolute convergence.
    for r in routes:
        r["stores"], _ = optimize_route_2opt(r["dc"], r["stores"])

    return [{"dc": r["dc"], "stores": r["stores"]} for r in routes]
# EVOLVE-BLOCK-END


def solve(instance):
    return build_routes(instance["dcs"], instance["stores"],
                        instance["truck_capacity"])
